// Mis Finanzas: servidor que conecta la app con tu base "Movimientos" de Notion.
//
// Variables que se configuran en Cloudflare (Settings -> Variables and Secrets):
//   NOTION_TOKEN  (secreto)  clave de la integración de Notion (empieza por ntn_)
//   APP_KEY       (secreto)  una clave tuya; va en el enlace de la app: ...workers.dev/?k=APP_KEY
//   DATABASE_ID   (texto)    id de la base Movimientos
//
// Este archivo se genera con build.py a partir de worker.template.js e ../index.html.
// Para cambiar la app edita esos archivos y vuelve a correr: python3 build.py

const APP_HTML = "<!doctype html>\n<html lang=\"es\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n<meta name=\"theme-color\" content=\"#0f6e5c\">\n<meta name=\"apple-mobile-web-app-capable\" content=\"yes\">\n<title>Mis Finanzas Mes a Mes</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Bricolage+Grotesque:opsz,wght@12..96,600;12..96,700&family=Figtree:wght@400;500;600;700&display=swap\">\n<style>\n:root{\n  color-scheme: light;\n  --bg:#f3f5f2;\n  --surface:#ffffff;\n  --surface-2:#e9ede8;\n  --ink:#14201b;\n  --ink-2:#4a5751;\n  --ink-3:#7d8983;\n  --line:rgba(20,32,27,.12);\n  --accent:#0f6e5c;\n  --accent-ink:#ffffff;\n  --accent-soft:#d6ebe4;\n  --pos:#12805c;\n  --neg:#c73b3a;\n  --neu:#5d6b87;\n  --warn:#a86b00;\n  --s1:#2a78d6; --s2:#eb6834; --s3:#1baf7a; --s4:#eda100;\n  --s5:#e87ba4; --s6:#008300; --s7:#4a3aa7; --s8:#e34948;\n  --shadow:0 10px 30px rgba(20,32,27,.12);\n  --display:\"Bricolage Grotesque\", \"Figtree\", system-ui, sans-serif;\n  --body:\"Figtree\", system-ui, -apple-system, \"Segoe UI\", Roboto, sans-serif;\n}\n@media (prefers-color-scheme: dark){\n  :root:not([data-theme=\"light\"]){\n    color-scheme: dark;\n    --bg:#0e1412; --surface:#17201c; --surface-2:#212c28;\n    --ink:#eef3f0; --ink-2:#b5c1bb; --ink-3:#85928c;\n    --line:rgba(238,243,240,.12);\n    --accent:#3fb89a; --accent-ink:#06231b; --accent-soft:#1d3a32;\n    --pos:#46c795; --neg:#ef7473; --neu:#9aa8c8; --warn:#e0a53a;\n    --s1:#3987e5; --s2:#d95926; --s3:#199e70; --s4:#c98500;\n    --s5:#d55181; --s6:#008300; --s7:#9085e9; --s8:#e66767;\n    --shadow:0 10px 30px rgba(0,0,0,.45);\n  }\n}\n:root[data-theme=\"dark\"]{\n  color-scheme: dark;\n  --bg:#0e1412; --surface:#17201c; --surface-2:#212c28;\n  --ink:#eef3f0; --ink-2:#b5c1bb; --ink-3:#85928c;\n  --line:rgba(238,243,240,.12);\n  --accent:#3fb89a; --accent-ink:#06231b; --accent-soft:#1d3a32;\n  --pos:#46c795; --neg:#ef7473; --neu:#9aa8c8; --warn:#e0a53a;\n  --s1:#3987e5; --s2:#d95926; --s3:#199e70; --s4:#c98500;\n  --s5:#d55181; --s6:#008300; --s7:#9085e9; --s8:#e66767;\n  --shadow:0 10px 30px rgba(0,0,0,.45);\n}\n*{box-sizing:border-box}\n[hidden]{display:none!important}\nhtml{-webkit-text-size-adjust:100%}\nbody{\n  margin:0; background:var(--bg); color:var(--ink);\n  font:15px/1.45 var(--body);\n  padding-top:env(safe-area-inset-top,0px);\n  padding-bottom:calc(96px + env(safe-area-inset-bottom,0px));\n}\n.wrap{max-width:760px; margin:0 auto; padding-inline:16px}\nbutton,input,select{font:inherit; color:inherit}\nbutton{cursor:pointer}\n:focus-visible{outline:2px solid var(--accent); outline-offset:2px}\n.num{font-variant-numeric:tabular-nums}\n\n/* Top bar */\n.top{\n  position:sticky; top:env(safe-area-inset-top,0px); z-index:20;\n  background:color-mix(in srgb, var(--bg) 88%, transparent);\n  backdrop-filter:saturate(1.4) blur(10px); -webkit-backdrop-filter:saturate(1.4) blur(10px);\n  border-bottom:1px solid var(--line);\n}\n.top .wrap{display:grid; gap:10px; padding-block:12px 10px}\n.brand{display:flex; align-items:center; justify-content:space-between; gap:12px}\n.brand h1{font:700 20px/1.1 var(--display); margin:0; letter-spacing:-.01em}\n.brand small{display:block; font:500 12px var(--body); color:var(--ink-3); letter-spacing:.04em; text-transform:uppercase}\n.iconbtn{\n  width:40px; height:40px; border-radius:12px; border:1px solid var(--line);\n  background:var(--surface); display:grid; place-items:center; flex:none;\n}\n.iconbtn svg{width:20px; height:20px}\n.monthnav{display:grid; grid-template-columns:44px 1fr 44px; align-items:center; gap:8px}\n.monthnav button.arrow{height:44px; border-radius:14px; border:1px solid var(--line); background:var(--surface); font-size:20px}\n.monthlabel{\n  text-align:center; font:700 22px/1.1 var(--display); letter-spacing:-.01em;\n  border:0; background:none; padding:6px 0; text-transform:capitalize;\n}\n.monthlabel span{display:block; font:500 12px var(--body); color:var(--ink-3); text-transform:none}\n.tabs{display:grid; grid-template-columns:repeat(3,1fr); background:var(--surface-2); padding:4px; border-radius:14px; gap:4px}\n.tabs button{border:0; background:none; padding:9px 4px; border-radius:10px; font-weight:600; color:var(--ink-2)}\n.tabs button[aria-selected=\"true\"]{background:var(--surface); color:var(--ink); box-shadow:0 1px 3px rgba(0,0,0,.12)}\n\nmain .wrap{display:grid; gap:18px; padding-block:18px}\nsection h2{font:700 17px/1.2 var(--display); margin:0 0 10px}\n.muted{color:var(--ink-3)}\n\n/* Example banner */\n.banner{\n  display:flex; flex-wrap:wrap; align-items:center; gap:10px; justify-content:space-between;\n  background:var(--accent-soft); color:var(--ink); border-radius:14px; padding:12px 14px; font-size:14px;\n}\n.banner button{border:0; background:var(--accent); color:var(--accent-ink); padding:8px 12px; border-radius:10px; font-weight:600}\n\n.banner.warn{background:color-mix(in srgb, var(--warn) 16%, var(--surface))}\n.loading{padding:28px 16px; text-align:center; color:var(--ink-3); font-weight:600}\n.brand small.sync{display:inline-flex; align-items:center; gap:6px}\n.sync::before{content:\"\"; width:7px; height:7px; border-radius:50%; background:var(--pos)}\n.sync[data-state=\"saving\"]::before{background:var(--warn)}\n.sync[data-state=\"error\"]::before{background:var(--neg)}\n.sync[data-state=\"local\"]::before{background:var(--ink-3)}\n\n/* Balance hero */\n.hero{background:var(--surface); border:1px solid var(--line); border-radius:20px; padding:18px; display:grid; gap:14px}\n.hero .lbl{font-size:12px; text-transform:uppercase; letter-spacing:.06em; color:var(--ink-3); font-weight:600}\n.hero .big{font:700 clamp(30px,8vw,40px)/1.05 var(--display); letter-spacing:-.02em}\n.kpis{display:grid; grid-template-columns:repeat(2,1fr); gap:10px}\n@media (min-width:560px){ .kpis{grid-template-columns:repeat(4,1fr)} }\n.kpi{background:var(--surface-2); border-radius:14px; padding:10px 12px; display:grid; gap:2px}\n.kpi .v{font-weight:700; font-size:16px}\n.kpi .l{font-size:12px; color:var(--ink-3)}\n.bar{height:8px; border-radius:99px; background:var(--surface-2); overflow:hidden; display:flex; gap:2px}\n.bar i{display:block; height:100%}\n.pos{color:var(--pos)} .neg{color:var(--neg)} .neu{color:var(--neu)}\n\n/* Lists */\n.card{background:var(--surface); border:1px solid var(--line); border-radius:18px; overflow:hidden}\n.chips{display:flex; gap:8px; overflow-x:auto; padding-bottom:2px; scrollbar-width:none}\n.chips::-webkit-scrollbar{display:none}\n.chip{flex:none; border:1px solid var(--line); background:var(--surface); padding:7px 12px; border-radius:99px; font-size:13px; font-weight:600; color:var(--ink-2)}\n.chip[aria-pressed=\"true\"]{background:var(--ink); color:var(--bg); border-color:var(--ink)}\n.search{width:100%; border:1px solid var(--line); background:var(--surface); border-radius:12px; padding:10px 12px}\n.group-h{display:flex; justify-content:space-between; align-items:baseline; padding:12px 14px 6px; font-size:12px; text-transform:uppercase; letter-spacing:.06em; color:var(--ink-3); font-weight:700}\n.row{\n  display:grid; grid-template-columns:28px 1fr auto; gap:10px; align-items:center;\n  padding:11px 14px; border-top:1px solid var(--line); width:100%; text-align:left; background:none; border-left:0; border-right:0; border-bottom:0;\n}\n.row:first-of-type{border-top:0}\n.check{\n  width:26px; height:26px; border-radius:8px; border:2px solid var(--line); background:none; display:grid; place-items:center; padding:0;\n}\n.check[aria-checked=\"true\"]{background:var(--accent); border-color:var(--accent); color:var(--accent-ink)}\n.check svg{width:14px; height:14px}\n.row .t{min-width:0}\n.row .d{font-weight:600; white-space:nowrap; overflow:hidden; text-overflow:ellipsis}\n.row .m{font-size:12px; color:var(--ink-3); display:flex; flex-wrap:wrap; gap:4px 8px; align-items:center}\n.row .a{font-weight:700; text-align:right; white-space:nowrap}\n.row.done .d{color:var(--ink-3)}\n.tag{display:inline-flex; align-items:center; gap:4px; font-size:11px; font-weight:700; padding:1px 7px; border-radius:99px; background:var(--surface-2); color:var(--ink-2)}\n.tag.rec{background:var(--accent-soft); color:var(--accent)}\n.tag.mod{background:color-mix(in srgb, var(--warn) 18%, transparent); color:var(--warn)}\n.empty{padding:26px 16px; text-align:center; color:var(--ink-3)}\n\n/* Charts */\n.chartcard{background:var(--surface); border:1px solid var(--line); border-radius:18px; padding:16px; display:grid; gap:10px}\n.chartcard header{display:flex; justify-content:space-between; align-items:baseline; gap:10px; flex-wrap:wrap}\n.chartcard h3{margin:0; font:700 16px var(--display)}\n.chartcard .sub{font-size:12px; color:var(--ink-3)}\n.cbox{position:relative; height:240px}\n.cbox.tall{height:280px}\n.legend{display:flex; flex-wrap:wrap; gap:6px 14px; font-size:13px; color:var(--ink-2)}\n.legend span{display:inline-flex; align-items:center; gap:6px}\n.legend i{width:10px; height:10px; border-radius:3px; display:inline-block}\n.catlist{display:grid; gap:8px}\n.catrow{display:grid; grid-template-columns:12px 1fr auto auto; gap:8px; align-items:center; font-size:14px}\n.catrow i{width:12px; height:12px; border-radius:4px}\n.catrow .p{color:var(--ink-3); font-size:12px; width:40px; text-align:right}\n.seg{display:flex; gap:6px}\n.seg button{border:1px solid var(--line); background:var(--surface); border-radius:10px; padding:5px 10px; font-size:12px; font-weight:600; color:var(--ink-2)}\n.seg button[aria-pressed=\"true\"]{background:var(--ink); color:var(--bg); border-color:var(--ink)}\n.tablewrap{overflow-x:auto}\ntable{border-collapse:collapse; width:100%; font-size:13px}\nth,td{padding:7px 8px; border-bottom:1px solid var(--line); text-align:right; white-space:nowrap}\nth:first-child,td:first-child{text-align:left}\nth{color:var(--ink-3); font-weight:600; font-size:12px}\n\n/* Settings */\n.settings{display:grid; gap:12px}\n.setting{background:var(--surface); border:1px solid var(--line); border-radius:16px; padding:14px; display:grid; gap:10px}\n.setting h3{margin:0; font:700 15px var(--display)}\n.setting p{margin:0; color:var(--ink-2); font-size:14px}\n.btnrow{display:flex; flex-wrap:wrap; gap:8px}\n.btn{border:1px solid var(--line); background:var(--surface-2); padding:10px 14px; border-radius:12px; font-weight:600}\n.btn.primary{background:var(--accent); color:var(--accent-ink); border-color:var(--accent)}\n.btn.danger{color:var(--neg)}\ntextarea{width:100%; min-height:90px; border:1px solid var(--line); border-radius:12px; background:var(--surface-2); color:var(--ink); padding:10px; font:12px/1.4 ui-monospace, Menlo, monospace}\n\n/* FAB */\n.fab{\n  position:fixed; right:max(16px, calc(50vw - 364px)); bottom:calc(20px + env(safe-area-inset-bottom,0px)); z-index:30;\n  display:flex; align-items:center; gap:8px; border:0; border-radius:18px; padding:15px 20px;\n  background:var(--accent); color:var(--accent-ink); font-weight:700; font-size:16px; box-shadow:var(--shadow);\n}\n.fab svg{width:20px; height:20px}\n\n/* Sheet */\n.scrim{position:fixed; inset:0; background:rgba(8,14,12,.45); z-index:40}\n.sheet{\n  position:fixed; left:0; right:0; bottom:0; z-index:50; max-height:92vh; overflow:auto;\n  background:var(--surface); border-radius:22px 22px 0 0; box-shadow:var(--shadow);\n  padding:8px 16px calc(18px + env(safe-area-inset-bottom,0px));\n  max-width:620px; margin:0 auto;\n  animation:up .22s ease-out;\n}\n@keyframes up{from{transform:translateY(24px); opacity:.6}to{transform:none; opacity:1}}\n@media (prefers-reduced-motion:reduce){.sheet{animation:none}}\n.grab{width:40px; height:5px; border-radius:9px; background:var(--line); margin:4px auto 10px}\n.sheet h2{font:700 20px var(--display); margin:0 0 12px}\n.form{display:grid; gap:12px}\n.field{display:grid; gap:5px}\n.field label, .field .fl{font-size:12px; font-weight:700; color:var(--ink-2); text-transform:uppercase; letter-spacing:.05em}\n.field input,.field select{\n  width:100%; border:1px solid var(--line); background:var(--surface-2); border-radius:12px; padding:12px; min-height:46px; font-size:16px;\n}\n.amount input{font:700 26px var(--display); padding:10px 12px}\n.two{display:grid; grid-template-columns:1fr 1fr; gap:10px}\n.typegrid{display:grid; grid-template-columns:repeat(auto-fit, minmax(92px,1fr)); gap:6px}\n.typegrid button, .freq button, .scope button{\n  border:1px solid var(--line); background:var(--surface-2); border-radius:12px; padding:10px 4px; font-weight:600; font-size:13px; color:var(--ink-2)\n}\n.typegrid button[aria-pressed=\"true\"]{background:var(--ink); color:var(--bg); border-color:var(--ink)}\n.freq{display:grid; grid-template-columns:1fr 1fr; gap:6px}\n.freq button{padding:12px 8px; display:grid; gap:2px; text-align:left}\n.freq button small{font-weight:500; font-size:12px; color:var(--ink-3)}\n.freq button[aria-pressed=\"true\"]{border-color:var(--accent); background:var(--accent-soft); color:var(--ink)}\n.scope{display:grid; gap:6px}\n.scope button{text-align:left; padding:12px}\n.scope button[aria-pressed=\"true\"]{border-color:var(--accent); background:var(--accent-soft); color:var(--ink)}\n.sheet .actions{display:grid; grid-template-columns:1fr 2fr; gap:8px; margin-top:4px}\n.sheet .actions .btn{padding:14px}\n.confirm{background:color-mix(in srgb, var(--neg) 10%, var(--surface)); border:1px solid color-mix(in srgb, var(--neg) 35%, transparent); border-radius:14px; padding:12px; display:grid; gap:8px}\n.confirm p{margin:0; font-size:14px}\n\n.toast{\n  position:fixed; left:50%; bottom:calc(92px + env(safe-area-inset-bottom,0px)); transform:translateX(-50%);\n  background:var(--ink); color:var(--bg); padding:10px 16px; border-radius:12px; font-weight:600; z-index:60; font-size:14px;\n  max-width:calc(100% - 32px);\n}\n</style>\n</head>\n<body>\n\n<header class=\"top\">\n  <div class=\"wrap\">\n    <div class=\"brand\">\n      <div>\n        <small id=\"sync\" class=\"sync\" data-state=\"local\">Guardado en este dispositivo</small>\n        <h1>Mis Finanzas</h1>\n      </div>\n      <button class=\"iconbtn\" id=\"themeBtn\" type=\"button\" aria-label=\"Cambiar tema claro/oscuro\">\n        <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M21 12.8A9 9 0 1 1 11.2 3a7 7 0 0 0 9.8 9.8z\"/></svg>\n      </button>\n    </div>\n    <div class=\"monthnav\">\n      <button class=\"arrow\" id=\"prevM\" type=\"button\" aria-label=\"Mes anterior\">‹</button>\n      <button class=\"monthlabel\" id=\"monthLbl\" type=\"button\" aria-label=\"Volver al mes actual\"></button>\n      <button class=\"arrow\" id=\"nextM\" type=\"button\" aria-label=\"Mes siguiente\">›</button>\n    </div>\n    <div class=\"tabs\" role=\"tablist\">\n      <button role=\"tab\" id=\"tab-resumen\" data-tab=\"resumen\" aria-selected=\"true\" type=\"button\">Resumen</button>\n      <button role=\"tab\" id=\"tab-mov\" data-tab=\"mov\" aria-selected=\"false\" type=\"button\">Movimientos</button>\n      <button role=\"tab\" id=\"tab-graf\" data-tab=\"graf\" aria-selected=\"false\" type=\"button\">Gráficos</button>\n    </div>\n  </div>\n</header>\n\n<main>\n  <div class=\"wrap\">\n    <div class=\"banner\" id=\"exBanner\" hidden>\n      <span>Estás viendo <b>datos de ejemplo</b>. Bórralos y empieza con los tuyos.</span>\n      <button type=\"button\" id=\"clearEx\">Borrar ejemplos</button>\n    </div>\n\n    <div class=\"banner warn\" id=\"noStore\" hidden>\n      <span>Aquí no se pueden guardar los cambios automáticamente. Antes de cerrar, ve a <b>Gráficos → Copiar copia</b>, o abre la app desde su enlace directo.</span>\n    </div>\n\n    <div class=\"banner warn\" id=\"errBanner\" hidden>\n      <span id=\"errMsg\">No se pudo conectar con Notion.</span>\n      <button type=\"button\" id=\"retryBtn\">Reintentar</button>\n    </div>\n\n    <div class=\"loading\" id=\"loading\" hidden>Cargando tus movimientos desde Notion…</div>\n\n    <!-- RESUMEN -->\n    <div id=\"view-resumen\" class=\"view\" style=\"display:grid; gap:18px\">\n      <section class=\"hero\" aria-label=\"Balance del mes\">\n        <div>\n          <div class=\"lbl\">Balance del mes</div>\n          <div class=\"big num\" id=\"hBalance\">$0</div>\n          <div class=\"muted\" id=\"hBalanceSub\" style=\"font-size:13px\"></div>\n        </div>\n        <div class=\"bar\" id=\"hBar\" aria-hidden=\"true\"></div>\n        <div class=\"kpis\">\n          <div class=\"kpi\"><span class=\"l\">Ingresos</span><span class=\"v num pos\" id=\"kIng\">$0</span></div>\n          <div class=\"kpi\"><span class=\"l\">Gastos</span><span class=\"v num neg\" id=\"kGas\">$0</span></div>\n          <div class=\"kpi\"><span class=\"l\">Inversión / ahorro</span><span class=\"v num neu\" id=\"kInv\">$0</span></div>\n          <div class=\"kpi\"><span class=\"l\">Pendiente por pagar</span><span class=\"v num\" id=\"kPend\">$0</span></div>\n        </div>\n      </section>\n\n      <section class=\"chartcard\" aria-label=\"Gastos por categoría\">\n        <header><h3>¿En qué se va la plata?</h3><span class=\"sub\" id=\"catSub\"></span></header>\n        <div class=\"cbox\"><canvas id=\"cDonut\" aria-label=\"Gráfico de gastos por categoría\" role=\"img\"></canvas></div>\n        <div class=\"catlist\" id=\"catList\"></div>\n      </section>\n\n      <section>\n        <h2>Próximos pagos del mes</h2>\n        <div class=\"card\" id=\"pendList\"></div>\n      </section>\n    </div>\n\n    <!-- MOVIMIENTOS -->\n    <div id=\"view-mov\" class=\"view\" hidden style=\"display:grid; gap:12px\">\n      <input class=\"search\" id=\"q\" type=\"search\" placeholder=\"Buscar por descripción, categoría o método…\" aria-label=\"Buscar movimientos\">\n      <div class=\"chips\" id=\"filterChips\" role=\"group\" aria-label=\"Filtrar\">\n        <button class=\"chip\" data-f=\"todos\" aria-pressed=\"true\" type=\"button\">Todos</button>\n        <button class=\"chip\" data-f=\"Ingreso\" aria-pressed=\"false\" type=\"button\">Ingresos</button>\n        <button class=\"chip\" data-f=\"Gasto\" aria-pressed=\"false\" type=\"button\">Gastos</button>\n        <button class=\"chip\" data-f=\"Inversión\" aria-pressed=\"false\" type=\"button\">Inversión</button>\n        <button class=\"chip\" data-f=\"mensual\" aria-pressed=\"false\" type=\"button\">Mensuales</button>\n        <button class=\"chip\" data-f=\"unica\" aria-pressed=\"false\" type=\"button\">Una vez</button>\n        <button class=\"chip\" data-f=\"pend\" aria-pressed=\"false\" type=\"button\">Sin pagar</button>\n      </div>\n      <div class=\"card\" id=\"movList\"></div>\n      <p class=\"muted\" style=\"font-size:13px; margin:0\">Toca un movimiento para editarlo. Toca el cuadro de la izquierda para marcarlo como pagado o recibido.</p>\n    </div>\n\n    <!-- GRAFICOS -->\n    <div id=\"view-graf\" class=\"view\" hidden style=\"display:grid; gap:18px\">\n      <div class=\"seg\" role=\"group\" aria-label=\"Rango\">\n        <button type=\"button\" data-r=\"6\" aria-pressed=\"true\">6 meses</button>\n        <button type=\"button\" data-r=\"12\" aria-pressed=\"false\">12 meses</button>\n      </div>\n      <section class=\"chartcard\">\n        <header><h3>Ingresos vs. gastos</h3><span class=\"sub\">Por mes, hasta el mes seleccionado</span></header>\n        <div class=\"legend\"><span><i style=\"background:var(--s1)\"></i>Ingresos</span><span><i style=\"background:var(--s2)\"></i>Gastos</span></div>\n        <div class=\"cbox tall\"><canvas id=\"cBars\" role=\"img\" aria-label=\"Barras de ingresos y gastos por mes\"></canvas></div>\n      </section>\n      <section class=\"chartcard\">\n        <header><h3>Balance de cada mes</h3><span class=\"sub\">Ingresos + reembolsos − gastos − inversión</span></header>\n        <div class=\"cbox\"><canvas id=\"cNet\" role=\"img\" aria-label=\"Balance mensual\"></canvas></div>\n      </section>\n      <section class=\"chartcard\">\n        <header><h3>Saldo acumulado</h3><span class=\"sub\">Suma de los balances del rango</span></header>\n        <div class=\"cbox\"><canvas id=\"cCum\" role=\"img\" aria-label=\"Saldo acumulado\"></canvas></div>\n      </section>\n      <section class=\"chartcard\">\n        <header><h3>Gastos por método de pago</h3><span class=\"sub\" id=\"payTitle\"></span></header>\n        <div class=\"cbox\" id=\"payBox\"><canvas id=\"cPay\" role=\"img\" aria-label=\"Gastos por método de pago\"></canvas></div>\n      </section>\n      <section class=\"chartcard\">\n        <header><h3>Tabla mensual</h3></header>\n        <div class=\"tablewrap\"><table id=\"tbl\"></table></div>\n      </section>\n\n      <section class=\"settings\" aria-label=\"Datos y copias de seguridad\">\n        <h2 style=\"margin:6px 0 0\">Tus datos</h2>\n        <div class=\"setting\" id=\"remoteData\" hidden>\n          <h3>Guardado en Notion</h3>\n          <p>Cada cambio se guarda en tu base <b>Movimientos</b> de Notion. También puedes ver y editar tus movimientos allá; toca «Recargar» para traer lo último.</p>\n          <div class=\"btnrow\"><button class=\"btn primary\" id=\"reloadBtn\" type=\"button\">Recargar desde Notion</button></div>\n        </div>\n        <div class=\"setting\" id=\"localBackup\">\n          <h3>Copia de seguridad</h3>\n          <p>Todo se guarda en este dispositivo. Descarga una copia de vez en cuando, o cópiala para pegarla en otro celular o computador.</p>\n          <div class=\"btnrow\">\n            <button class=\"btn primary\" id=\"bkDown\" type=\"button\">Descargar copia (.json)</button>\n            <button class=\"btn\" id=\"bkCopy\" type=\"button\">Copiar copia</button>\n            <label class=\"btn\" for=\"bkFile\" style=\"display:inline-flex;align-items:center\">Restaurar desde archivo</label>\n            <input id=\"bkFile\" type=\"file\" accept=\".json,application/json\" hidden>\n          </div>\n          <textarea id=\"bkPaste\" placeholder=\"…o pega aquí una copia y toca «Restaurar texto pegado»\" aria-label=\"Pegar copia de seguridad\"></textarea>\n          <div class=\"btnrow\"><button class=\"btn\" id=\"bkRestore\" type=\"button\">Restaurar texto pegado</button></div>\n        </div>\n        <div class=\"setting\">\n          <h3>Exportar a CSV</h3>\n          <p>Con las columnas de tu base «Registro de Finanzas Personales»: Descripción, Tipo, Gasto, Ingreso, Fecha, Método de Pago. Sirve para Excel o para importar en Notion (••• → Merge with CSV).</p>\n          <div class=\"btnrow\">\n            <button class=\"btn primary\" id=\"csvMonth\" type=\"button\">CSV de este mes</button>\n            <button class=\"btn\" id=\"csvYear\" type=\"button\">CSV del año</button>\n          </div>\n        </div>\n        <div class=\"setting\" id=\"localWipe\">\n          <h3>Empezar de cero</h3>\n          <div class=\"btnrow\"><button class=\"btn danger\" id=\"wipe\" type=\"button\">Borrar todos los datos</button></div>\n          <div class=\"confirm\" id=\"wipeConfirm\" hidden>\n            <p>Se borrarán todos tus movimientos de este dispositivo. ¿Seguro?</p>\n            <div class=\"btnrow\"><button class=\"btn\" id=\"wipeNo\" type=\"button\">Cancelar</button><button class=\"btn danger\" id=\"wipeYes\" type=\"button\">Sí, borrar todo</button></div>\n          </div>\n        </div>\n      </section>\n    </div>\n  </div>\n</main>\n\n<button class=\"fab\" id=\"addBtn\" type=\"button\">\n  <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\"><path d=\"M12 5v14M5 12h14\"/></svg>\n  Agregar\n</button>\n\n<div class=\"scrim\" id=\"scrim\" hidden></div>\n<div class=\"sheet\" id=\"sheet\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"sheetTitle\" hidden>\n  <div class=\"grab\"></div>\n  <h2 id=\"sheetTitle\">Nuevo movimiento</h2>\n  <form class=\"form\" id=\"form\" autocomplete=\"off\">\n    <div class=\"field\">\n      <span class=\"fl\">Tipo</span>\n      <div class=\"typegrid\" id=\"fTipo\"></div>\n    </div>\n    <div class=\"field amount\">\n      <label for=\"fMonto\">Monto (COP)</label>\n      <input id=\"fMonto\" inputmode=\"numeric\" placeholder=\"$0\" required>\n    </div>\n    <div class=\"field\">\n      <label for=\"fDesc\">Descripción</label>\n      <input id=\"fDesc\" placeholder=\"Ej: Arriendo, Salario, Mercado\" required list=\"descList\">\n      <datalist id=\"descList\"></datalist>\n    </div>\n    <div class=\"two\">\n      <div class=\"field\">\n        <label for=\"fCat\">Categoría</label>\n        <input id=\"fCat\" list=\"catOpts\" placeholder=\"Ej: Vivienda\">\n        <datalist id=\"catOpts\"></datalist>\n      </div>\n      <div class=\"field\">\n        <label for=\"fMet\">Método de pago</label>\n        <select id=\"fMet\"></select>\n      </div>\n    </div>\n    <div class=\"field\">\n      <span class=\"fl\">¿Se repite?</span>\n      <div class=\"freq\" id=\"fFreq\">\n        <button type=\"button\" data-v=\"unica\" aria-pressed=\"true\">Solo una vez<small>Solo en esta fecha</small></button>\n        <button type=\"button\" data-v=\"mensual\" aria-pressed=\"false\">Cada mes<small>Se copia a los meses siguientes</small></button>\n      </div>\n    </div>\n    <div class=\"two\" id=\"dateRow\">\n      <div class=\"field\" id=\"fFechaWrap\">\n        <label for=\"fFecha\">Fecha</label>\n        <input id=\"fFecha\" type=\"date\">\n      </div>\n      <div class=\"field\" id=\"fDiaWrap\" hidden>\n        <label for=\"fDia\">Día del mes</label>\n        <input id=\"fDia\" type=\"number\" min=\"1\" max=\"31\" inputmode=\"numeric\">\n      </div>\n      <div class=\"field\" id=\"fFinWrap\" hidden>\n        <label for=\"fFin\">Hasta (opcional)</label>\n        <input id=\"fFin\" type=\"month\">\n      </div>\n    </div>\n    <div class=\"field\" id=\"scopeWrap\" hidden>\n      <span class=\"fl\">Aplicar cambios a</span>\n      <div class=\"scope\" id=\"fScope\">\n        <button type=\"button\" data-v=\"mes\" aria-pressed=\"true\">Solo este mes</button>\n        <button type=\"button\" data-v=\"desde\" aria-pressed=\"false\">Este mes y los siguientes</button>\n        <button type=\"button\" data-v=\"todos\" aria-pressed=\"false\">Todos los meses</button>\n      </div>\n    </div>\n    <div class=\"confirm\" id=\"delConfirm\" hidden>\n      <p id=\"delMsg\">¿Eliminar este movimiento?</p>\n      <div class=\"btnrow\" id=\"delBtns\"></div>\n    </div>\n    <div class=\"actions\">\n      <button class=\"btn\" type=\"button\" id=\"cancelBtn\">Cancelar</button>\n      <button class=\"btn primary\" type=\"submit\" id=\"saveBtn\">Guardar</button>\n    </div>\n    <button class=\"btn danger\" type=\"button\" id=\"delBtn\" hidden>Eliminar</button>\n  </form>\n</div>\n\n<div class=\"toast\" id=\"toast\" hidden></div>\n\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/Chart.js/4.4.1/chart.umd.min.js\"></script>\n<script>\n(function(){\n\"use strict\";\n\n/* ---------- Constantes (tomadas de tu base de Notion) ---------- */\nconst TIPOS = [\"Gasto\",\"Ingreso\",\"Inversión\",\"Transferencia\",\"Reembolso\"];\nconst SIGNO = {\"Ingreso\":1,\"Reembolso\":1,\"Gasto\":-1,\"Inversión\":-1,\"Transferencia\":0};\nconst METODOS = [\"Nequi\",\"Bancolombia\",\"Bancoomeva\",\"Lulo\",\"Nu\",\"Efectivo\",\"Pse\",\"Transferencia\"];\nconst CATS_GASTO = [\"Vivienda\",\"Servicios\",\"Mercado\",\"Transporte\",\"Deudas y tarjetas\",\"Salud\",\"Educación\",\"Suscripciones\",\"Entretenimiento\",\"Ropa y personal\",\"Otros\"];\nconst CATS_ING = [\"Salario\",\"Freelance\",\"Ventas\",\"Otros\"];\nconst CATS_INV = [\"Ahorro\",\"CDT\",\"Acciones\",\"Cripto\",\"Oro\",\"Fondo\"];\nconst LOCAL_KEY = \"finanzas_filas_v2\";\nconst MESES = [\"enero\",\"febrero\",\"marzo\",\"abril\",\"mayo\",\"junio\",\"julio\",\"agosto\",\"septiembre\",\"octubre\",\"noviembre\",\"diciembre\"];\n\n// Si la app la sirve el servidor (worker), trae window.FIN_CONFIG y guarda en Notion.\nconst CFG = window.FIN_CONFIG || null;\nconst REMOTE = !!(CFG && CFG.key);\n\n/* ---------- Utilidades ---------- */\nconst $ = s => document.querySelector(s);\nconst fmt = new Intl.NumberFormat(\"es-CO\",{style:\"currency\",currency:\"COP\",maximumFractionDigits:0});\nconst money = n => fmt.format(Math.round(n||0));\nconst short = n => {\n  const a = Math.abs(n);\n  if (a >= 1e6) return (n/1e6).toLocaleString(\"es-CO\",{maximumFractionDigits:1})+\" M\";\n  if (a >= 1e3) return Math.round(n/1e3).toLocaleString(\"es-CO\")+\" mil\";\n  return Math.round(n).toLocaleString(\"es-CO\");\n};\nconst rid = () => Math.random().toString(36).slice(2,8)+Date.now().toString(36).slice(-4);\nconst pad = n => String(n).padStart(2,\"0\");\nconst ymOf = d => d.slice(0,7);\nconst ymAdd = (ym,k) => { let [y,m]=ym.split(\"-\").map(Number); m+=k; y+=Math.floor((m-1)/12); m=((m-1)%12+12)%12+1; return y+\"-\"+pad(m); };\nconst ymNow = () => { const d=new Date(); return d.getFullYear()+\"-\"+pad(d.getMonth()+1); };\nconst daysIn = ym => { const [y,m]=ym.split(\"-\").map(Number); return new Date(y,m,0).getDate(); };\nconst dateIn = (ym,dia) => ym+\"-\"+pad(Math.min(Math.max(1,dia||1), daysIn(ym)));\nconst ymLabel = ym => { const [y,m]=ym.split(\"-\").map(Number); return MESES[m-1]+\" \"+y; };\nconst ymShort = ym => { const [y,m]=ym.split(\"-\").map(Number); return MESES[m-1].slice(0,3)+\" \"+String(y).slice(2); };\nconst parseMonto = s => Number(String(s).replace(/[^\\d]/g,\"\"))||0;\nconst esc = s => String(s??\"\").replace(/[&<>\"']/g,c=>({\"&\":\"&amp;\",\"<\":\"&lt;\",\">\":\"&gt;\",'\"':\"&quot;\",\"'\":\"&#39;\"}[c]));\nconst cssv = n => getComputedStyle(document.documentElement).getPropertyValue(n).trim();\n\n/* ---------- Ítems mensuales ----------\n   Cada mes es una fila propia (así se ve y se edita en Notion).\n   Las filas de un mismo ítem mensual comparten \"serie\": \"id|hasta|día|a\".\n   \"a\" marca un mes ajustado solo para ese mes: no se usa como modelo de los meses nuevos. */\nfunction parseSerie(r){\n  if (!r.serie) return null;\n  const [id, fin, dia, aj] = r.serie.split(\"|\");\n  return {id, fin: fin || null, dia: Number(dia) || Number(r.fecha.slice(8)) || 1, aj: aj === \"a\"};\n}\nconst mkSerie = (id, fin, dia, aj) => `${id}|${fin||\"\"}|${dia}` + (aj ? \"|a\" : \"\");\nconst serieId = r => r.serie ? r.serie.split(\"|\")[0] : null;\nconst seriesRows = id => rows.filter(r => serieId(r) === id).sort((a,b)=>a.fecha.localeCompare(b.fecha));\nfunction serieFin(list){\n  const fins = list.map(r=>parseSerie(r).fin).filter(Boolean).sort();\n  return fins[0] || null;\n}\n\n/* ---------- Estado ---------- */\nlet rows = [];          // filas cargadas\nlet loaded = null;      // {from:'YYYY-MM', to:'YYYY-MM'} en modo Notion\nlet cur = ymNow();\nlet tab = \"resumen\";\nlet filtro = \"todos\";\nlet rango = 6;\nlet isSample = false;\n\nlet canStore = false;\ntry{ localStorage.setItem(\"fin_test\",\"1\"); localStorage.removeItem(\"fin_test\"); canStore = true; }catch(e){}\n\n/* ---------- Guardado ---------- */\n// Modo local: todas las filas en localStorage.\nfunction localLoad(){\n  try{ const raw = localStorage.getItem(LOCAL_KEY); if (raw){ const s=JSON.parse(raw); if (s && Array.isArray(s.rows)) return s; } }catch(e){}\n  return {sample:true, rows: sampleRows()};\n}\nfunction localSave(){ try{ localStorage.setItem(LOCAL_KEY, JSON.stringify({sample:isSample, rows})); }catch(e){} }\n\n// Modo Notion: cola de operaciones hacia el servidor, en orden.\nconst idMap = {};\nlet queue = Promise.resolve();\nlet pending = 0, syncError = null;\nconst realId = id => idMap[id] || id;\nconst findRow = id => rows.find(r => r.id === id || r.id === idMap[id]);\n\nasync function api(method, path, body){\n  const res = await fetch(CFG.api + path, {\n    method, headers: {\"content-type\":\"application/json\",\"x-app-key\":CFG.key},\n    body: body ? JSON.stringify(body) : undefined\n  });\n  let data = {}; try{ data = await res.json(); }catch(e){}\n  if (!res.ok) throw new Error(data.error || (\"Error \" + res.status));\n  return data;\n}\nconst chunks = (arr,n) => { const out=[]; for(let i=0;i<arr.length;i+=n) out.push(arr.slice(i,i+n)); return out; };\n\nasync function runOp(op){\n  if (op.t === \"create\"){\n    for (const part of chunks(op.rows, 25)){\n      const res = await api(\"POST\", \"/rows\", {rows: part.map(({id, ...r}) => r)});\n      res.rows.forEach((srv, i) => { const tmp = part[i].id; idMap[tmp] = srv.id; const r = rows.find(x => x.id === tmp); if (r) r.id = srv.id; });\n    }\n  } else if (op.t === \"update\"){\n    for (const part of chunks(op.updates, 25))\n      await api(\"PATCH\", \"/rows\", {updates: part.map(u => ({...u, id: realId(u.id)}))});\n  } else if (op.t === \"remove\"){\n    for (const part of chunks(op.ids, 25))\n      await api(\"POST\", \"/rows/delete\", {ids: part.map(realId)});\n  } else if (op.t === \"removeSeries\"){\n    let more = true, guard = 0;\n    while (more && guard++ < 50){ const res = await api(\"POST\", \"/series/delete\", {serie: op.serie, desde: op.desde || null}); more = !!res.remaining; }\n  }\n}\nfunction send(op){\n  if (!REMOTE){ localSave(); return; }\n  pending++; setSync();\n  queue = queue.then(() => runOp(op)).catch(err => {\n    syncError = err.message || \"No se pudo guardar\";\n    showError(\"No se pudo guardar en Notion: \" + syncError + \". Toca «Reintentar» para recargar tus datos.\");\n  }).finally(() => { pending--; setSync(); });\n}\nfunction setSync(){\n  const el = $(\"#sync\");\n  if (!REMOTE){ el.dataset.state = \"local\"; el.textContent = \"Guardado en este dispositivo\"; return; }\n  if (syncError){ el.dataset.state = \"error\"; el.textContent = \"Sin guardar\"; }\n  else if (pending){ el.dataset.state = \"saving\"; el.textContent = \"Guardando en Notion…\"; }\n  else { el.dataset.state = \"ok\"; el.textContent = \"Guardado en Notion\"; }\n}\nfunction showError(msg){ $(\"#errMsg\").textContent = msg; $(\"#errBanner\").hidden = false; }\n\n// Trae de Notion los meses necesarios (12 meses atrás del mes visto).\nasync function ensureRange(ym){\n  if (!REMOTE) return true;\n  const need = {from: ymAdd(ym, -11), to: ym > ymNow() ? ym : ymNow()};\n  if (loaded && loaded.from <= need.from && loaded.to >= need.to) return true;\n  const from = loaded ? (need.from < loaded.from ? need.from : loaded.from) : need.from;\n  const to = loaded ? (need.to > loaded.to ? need.to : loaded.to) : need.to;\n  $(\"#loading\").hidden = false;\n  try{\n    await queue;\n    const res = await api(\"GET\", `/rows?from=${from}-01&to=${to}-${daysIn(to)}`);\n    rows = res.rows;\n    loaded = {from, to};\n    $(\"#errBanner\").hidden = true; syncError = null; setSync();\n    return true;\n  }catch(err){\n    showError(err.message === \"Clave incorrecta\" ? \"El enlace no tiene la clave correcta. Revisa el enlace de la app.\" : \"No se pudo conectar con Notion (\" + err.message + \").\");\n    return false;\n  }finally{ $(\"#loading\").hidden = true; }\n}\n\n// Crea las filas que faltan de cada ítem mensual hasta el mes visto.\nfunction materialize(ym){\n  if (ym > ymAdd(ymNow(), 12)) return;\n  const ids = [...new Set(rows.map(serieId).filter(Boolean))];\n  const nuevos = [];\n  for (const id of ids){\n    const list = seriesRows(id);\n    const fin = serieFin(list);\n    const upto = list.filter(r => ymOf(r.fecha) <= ym);\n    if (!upto.length) continue;\n    const lastYm = ymOf(upto[upto.length-1].fecha);\n    if (lastYm === ym) continue;\n    const tpl = [...upto].reverse().find(r => !r.omit && !parseSerie(r).aj) || [...upto].reverse().find(r => !r.omit) || upto[upto.length-1];\n    const dia = parseSerie(tpl).dia;\n    const have = new Set(list.map(r => ymOf(r.fecha)));\n    for (let m = ymAdd(lastYm, 1); m <= ym; m = ymAdd(m, 1)){\n      if (fin && m > fin) break;\n      if (have.has(m)) continue;\n      nuevos.push({id: \"tmp_\"+rid(), desc: tpl.desc, tipo: tpl.tipo, monto: tpl.monto, cat: tpl.cat, met: tpl.met,\n        frec: \"mensual\", pagado: false, omit: false, serie: mkSerie(id, fin, dia), fecha: dateIn(m, dia)});\n    }\n  }\n  if (nuevos.length){ rows.push(...nuevos); send({t:\"create\", rows: nuevos}); }\n}\n\nasync function goTo(ym){\n  cur = ym;\n  render();\n  if (await ensureRange(cur)){ materialize(cur); render(); }\n}\n\n/* ---------- Datos de ejemplo (solo modo local) ---------- */\nfunction sampleRows(){\n  const now = ymNow(), out = [];\n  const serie = (tipo, desc, monto, cat, met, dia, meses, extra={}) => {\n    const id = rid();\n    for (let k = meses; k >= 0; k--){\n      const m = ymAdd(now, -k);\n      out.push({id: rid(), desc, tipo, monto: extra.montos?.[k] ?? monto, cat, met, frec: \"mensual\",\n        pagado: k > 0, omit: false, serie: mkSerie(id, extra.fin || null, dia, extra.montos?.[k] != null), fecha: dateIn(m, dia)});\n    }\n  };\n  const one = (tipo, desc, monto, cat, met, k, dia, pagado=true) => out.push({id: rid(), desc, tipo, monto, cat, met, frec: \"unica\", pagado, omit: false, serie: \"\", fecha: dateIn(ymAdd(now,-k), dia)});\n  serie(\"Ingreso\",\"Salario\",4200000,\"Salario\",\"Bancolombia\",30,5);\n  serie(\"Gasto\",\"Arriendo\",1300000,\"Vivienda\",\"Bancolombia\",5,5);\n  serie(\"Gasto\",\"Servicios públicos\",280000,\"Servicios\",\"Pse\",12,5,{montos:{1:305000}});\n  serie(\"Gasto\",\"Internet y celular\",135000,\"Servicios\",\"Nequi\",15,5);\n  serie(\"Gasto\",\"Mercado\",650000,\"Mercado\",\"Nu\",8,5,{montos:{4:720000,2:590000}});\n  serie(\"Gasto\",\"Transporte\",220000,\"Transporte\",\"Nequi\",1,5);\n  serie(\"Gasto\",\"Netflix\",38900,\"Suscripciones\",\"Nu\",20,5);\n  serie(\"Inversión\",\"Ahorro programado\",400000,\"Ahorro\",\"Bancoomeva\",2,5);\n  serie(\"Gasto\",\"Cuota tarjeta\",310000,\"Deudas y tarjetas\",\"Bancolombia\",18,5,{fin: ymAdd(now,2)});\n  one(\"Ingreso\",\"Venta de bicicleta\",750000,\"Ventas\",\"Nequi\",3,14);\n  one(\"Gasto\",\"Regalo cumpleaños\",180000,\"Otros\",\"Efectivo\",3,22);\n  one(\"Gasto\",\"Cita odontología\",150000,\"Salud\",\"Lulo\",1,9);\n  one(\"Ingreso\",\"Proyecto freelance\",1200000,\"Freelance\",\"Nequi\",0,10,false);\n  one(\"Gasto\",\"Salida a cine\",62000,\"Entretenimiento\",\"Nu\",0,7);\n  one(\"Reembolso\",\"Devolución compra\",90000,\"Otros\",\"Nu\",2,16);\n  out.filter(r => ymOf(r.fecha) === now && [\"Arriendo\",\"Transporte\"].includes(r.desc)).forEach(r => r.pagado = true);\n  return out;\n}\n\n/* ---------- Cálculos del mes ---------- */\nfunction occurrences(ym){\n  return rows.filter(r => r.fecha && ymOf(r.fecha) === ym && !r.omit)\n    .sort((a,b) => a.fecha.localeCompare(b.fecha) || a.desc.localeCompare(b.desc));\n}\nfunction totals(ym){\n  const t = {Ingreso:0, Gasto:0, \"Inversión\":0, Transferencia:0, Reembolso:0, pend:0};\n  for (const r of occurrences(ym)){\n    t[r.tipo] = (t[r.tipo]||0) + r.monto;\n    if (!r.pagado && (r.tipo===\"Gasto\" || r.tipo===\"Inversión\")) t.pend += r.monto;\n  }\n  t.entra = t.Ingreso + t.Reembolso;\n  t.sale = t.Gasto + t[\"Inversión\"];\n  t.balance = t.entra - t.sale;\n  return t;\n}\n\n/* ---------- Render ---------- */\nfunction render(){\n  const isNow = cur === ymNow();\n  $(\"#monthLbl\").innerHTML = esc(ymLabel(cur)) + `<span>${isNow ? \"Mes actual\" : \"Toca para volver al mes actual\"}</span>`;\n  $(\"#exBanner\").hidden = !isSample;\n  $(\"#noStore\").hidden = REMOTE || canStore;\n  $(\"#remoteData\").hidden = !REMOTE;\n  $(\"#localBackup\").hidden = REMOTE;\n  $(\"#localWipe\").hidden = REMOTE;\n  for (const b of document.querySelectorAll(\".tabs button\")) b.setAttribute(\"aria-selected\", String(b.dataset.tab === tab));\n  $(\"#view-resumen\").hidden = tab !== \"resumen\";\n  $(\"#view-mov\").hidden = tab !== \"mov\";\n  $(\"#view-graf\").hidden = tab !== \"graf\";\n  if (tab === \"resumen\") renderResumen();\n  if (tab === \"mov\") renderMov();\n  if (tab === \"graf\") renderGraf();\n  setSync();\n  try{ sessionStorage.setItem(\"fin_tab\", tab); }catch(e){}\n}\n\nfunction renderResumen(){\n  const t = totals(cur);\n  const b = $(\"#hBalance\");\n  b.textContent = money(t.balance);\n  b.className = \"big num \" + (t.balance >= 0 ? \"pos\" : \"neg\");\n  const ahorro = t.entra > 0 ? Math.round((t.entra - t.Gasto) / t.entra * 100) : 0;\n  $(\"#hBalanceSub\").textContent = t.entra > 0\n    ? `Te queda el ${Math.max(0, Math.round(t.balance / t.entra * 100))}% de lo que entra · tasa de ahorro (incl. inversión) ${ahorro}%`\n    : \"Aún no hay ingresos este mes\";\n  $(\"#kIng\").textContent = money(t.entra);\n  $(\"#kGas\").textContent = money(t.Gasto);\n  $(\"#kInv\").textContent = money(t[\"Inversión\"]);\n  $(\"#kPend\").textContent = money(t.pend);\n  const tot = Math.max(t.entra, t.sale, 1);\n  $(\"#hBar\").innerHTML = `<i style=\"width:${t.Gasto/tot*100}%;background:var(--s2)\"></i><i style=\"width:${t[\"Inversión\"]/tot*100}%;background:var(--s7)\"></i><i style=\"width:${Math.max(0,t.balance)/tot*100}%;background:var(--s3)\"></i>`;\n\n  const cats = {};\n  for (const r of occurrences(cur)) if (r.tipo === \"Gasto\"){ const c = r.cat || \"Sin categoría\"; cats[c] = (cats[c]||0) + r.monto; }\n  let arr = Object.entries(cats).sort((a,b) => b[1]-a[1]);\n  if (arr.length > 7){ const rest = arr.slice(6).reduce((s,x) => s+x[1], 0); arr = arr.slice(0,6).concat([[\"Otras\", rest]]); }\n  const cols = [\"--s1\",\"--s2\",\"--s3\",\"--s4\",\"--s5\",\"--s6\",\"--s7\"].map(cssv);\n  const sum = arr.reduce((s,x) => s+x[1], 0);\n  $(\"#catSub\").textContent = sum ? money(sum) + \" en gastos\" : \"\";\n  $(\"#catList\").innerHTML = arr.length ? arr.map((x,i) => `<div class=\"catrow\"><i style=\"background:${cols[i]}\"></i><span>${esc(x[0])}</span><b class=\"num\">${money(x[1])}</b><span class=\"p num\">${Math.round(x[1]/sum*100)}%</span></div>`).join(\"\")\n    : `<div class=\"empty\">Sin gastos registrados en ${esc(ymLabel(cur))}.</div>`;\n  drawDonut(arr, cols);\n\n  const pend = occurrences(cur).filter(r => !r.pagado && r.tipo !== \"Transferencia\");\n  $(\"#pendList\").innerHTML = pend.length ? pend.map(rowHTML).join(\"\")\n    : `<div class=\"empty\">${occurrences(cur).length ? \"Todo al día este mes.\" : \"Aún no hay movimientos este mes. Toca <b>Agregar</b> para crear el primero.\"}</div>`;\n}\n\nfunction rowHTML(r){\n  const s = SIGNO[r.tipo] ?? 0;\n  const cls = s > 0 ? \"pos\" : s < 0 ? (r.tipo === \"Inversión\" ? \"neu\" : \"neg\") : \"\";\n  const sign = s > 0 ? \"+\" : s < 0 ? \"−\" : \"\";\n  const label = r.tipo === \"Ingreso\" || r.tipo === \"Reembolso\" ? \"recibido\" : \"pagado\";\n  const dd = Number(r.fecha.slice(8)), mm = MESES[Number(r.fecha.slice(5,7))-1].slice(0,3);\n  return `<div class=\"row ${r.pagado ? \"done\" : \"\"}\" data-id=\"${esc(r.id)}\" role=\"button\" tabindex=\"0\">\n    <button class=\"check\" type=\"button\" role=\"checkbox\" aria-checked=\"${!!r.pagado}\" aria-label=\"Marcar como ${label}\" data-check=\"1\">\n      <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" ${r.pagado ? \"\" : \"style='opacity:0'\"}><path d=\"M5 12.5l4.5 4.5L19 7.5\"/></svg>\n    </button>\n    <div class=\"t\">\n      <div class=\"d\">${esc(r.desc)}</div>\n      <div class=\"m\"><span>${dd} ${mm}</span>${r.cat ? `<span>· ${esc(r.cat)}</span>` : \"\"}${r.met ? `<span>· ${esc(r.met)}</span>` : \"\"}\n        ${r.serie ? '<span class=\"tag rec\">↻ Mensual</span>' : \"\"}${r.serie && parseSerie(r).aj ? '<span class=\"tag mod\">Ajustado este mes</span>' : \"\"}${r.tipo !== \"Gasto\" && r.tipo !== \"Ingreso\" ? `<span class=\"tag\">${esc(r.tipo)}</span>` : \"\"}</div>\n    </div>\n    <div class=\"a num ${cls}\">${sign}${money(r.monto)}</div>\n  </div>`;\n}\n\nfunction renderMov(){\n  const q = $(\"#q\").value.trim().toLowerCase();\n  let occ = occurrences(cur);\n  if (filtro === \"mensual\") occ = occ.filter(r => r.serie);\n  else if (filtro === \"unica\") occ = occ.filter(r => !r.serie);\n  else if (filtro === \"pend\") occ = occ.filter(r => !r.pagado);\n  else if (filtro !== \"todos\") occ = occ.filter(r => r.tipo === filtro);\n  if (q) occ = occ.filter(r => [r.desc, r.cat, r.met, r.tipo].join(\" \").toLowerCase().includes(q));\n  const groups = [[\"Entradas\", r => SIGNO[r.tipo] > 0], [\"Salidas\", r => SIGNO[r.tipo] < 0], [\"Transferencias\", r => !SIGNO[r.tipo]]];\n  let html = \"\";\n  for (const [name, fn] of groups){\n    const g = occ.filter(fn); if (!g.length) continue;\n    const s = g.reduce((a,r) => a + r.monto, 0);\n    html += `<div class=\"group-h\"><span>${name} · ${g.length}</span><span class=\"num\">${money(s)}</span></div>` + g.map(rowHTML).join(\"\");\n  }\n  $(\"#movList\").innerHTML = html || `<div class=\"empty\">No hay movimientos ${filtro !== \"todos\" || q ? \"con ese filtro \" : \"\"}en ${esc(ymLabel(cur))}.<br>Toca <b>Agregar</b> para crear uno.</div>`;\n}\n\n/* ---------- Gráficos ---------- */\nif (window.Chart){ Chart.defaults.font.family = \"Figtree, system-ui, -apple-system, Segoe UI, Roboto, sans-serif\"; }\nconst charts = {};\nfunction baseOpts(){\n  const ink2 = cssv(\"--ink-2\"), grid = cssv(\"--line\");\n  return {\n    responsive: true, maintainAspectRatio: false, animation: {duration: 250},\n    interaction: {mode: \"index\", intersect: false},\n    plugins: {legend: {display: false}, tooltip: {callbacks: {label: c => ` ${c.dataset.label}: ${money(c.parsed.y ?? c.parsed)}`}}},\n    scales: {\n      x: {grid: {display: false}, ticks: {color: ink2}, border: {color: grid}},\n      y: {grid: {color: grid}, border: {display: false}, ticks: {color: ink2, callback: v => short(v), maxTicksLimit: 5}}\n    }\n  };\n}\nfunction mk(id, cfg){\n  const c = document.getElementById(id);\n  if (!window.Chart){ if (c && !c.dataset.nochart){ c.dataset.nochart = \"1\"; c.parentElement.innerHTML = '<div class=\"empty\">No se pudo cargar el gráfico. Revisa tu conexión a internet.</div>'; } return; }\n  if (charts[id]) charts[id].destroy();\n  charts[id] = new Chart(c, cfg);\n}\nfunction drawDonut(arr, cols){\n  mk(\"cDonut\", {type: \"doughnut\",\n    data: {labels: arr.map(x => x[0]), datasets: [{label: \"Gasto\", data: arr.map(x => x[1]), backgroundColor: cols.slice(0, arr.length), borderColor: cssv(\"--surface\"), borderWidth: 2, borderRadius: 4, hoverOffset: 6}]},\n    options: {responsive: true, maintainAspectRatio: false, cutout: \"66%\", plugins: {legend: {display: false}, tooltip: {callbacks: {label: c => ` ${c.label}: ${money(c.parsed)}`}}}}\n  });\n}\nfunction renderGraf(){\n  const months = []; for (let k = rango-1; k >= 0; k--) months.push(ymAdd(cur, -k));\n  const T = months.map(totals);\n  const labels = months.map(ymShort);\n  const s1 = cssv(\"--s1\"), s2 = cssv(\"--s2\"), pos = cssv(\"--pos\"), neg = cssv(\"--neg\"), acc = cssv(\"--accent\");\n  mk(\"cBars\", {type: \"bar\", data: {labels, datasets: [\n      {label: \"Ingresos\", data: T.map(t => t.entra), backgroundColor: s1, borderRadius: 4, borderSkipped: \"bottom\", maxBarThickness: 22},\n      {label: \"Gastos\", data: T.map(t => t.Gasto), backgroundColor: s2, borderRadius: 4, borderSkipped: \"bottom\", maxBarThickness: 22}\n    ]}, options: {...baseOpts(), datasets: {bar: {categoryPercentage: .7, barPercentage: .9}}}});\n  mk(\"cNet\", {type: \"bar\", data: {labels, datasets: [{label: \"Balance\", data: T.map(t => t.balance),\n      backgroundColor: T.map(t => t.balance >= 0 ? pos : neg), borderRadius: 4, borderSkipped: false, maxBarThickness: 26}]}, options: baseOpts()});\n  let a0 = 0; const cum = T.map(t => a0 += t.balance);\n  mk(\"cCum\", {type: \"line\", data: {labels, datasets: [{label: \"Saldo acumulado\", data: cum, borderColor: acc, borderWidth: 2,\n      backgroundColor: acc + \"22\", fill: true, tension: .3, pointRadius: cum.map((_,i) => i === cum.length-1 ? 5 : 0), pointBackgroundColor: acc, pointHoverRadius: 5}]}, options: baseOpts()});\n\n  const pay = {};\n  for (const r of occurrences(cur)) if (r.tipo === \"Gasto\"){ const m = r.met || \"Sin método\"; pay[m] = (pay[m]||0) + r.monto; }\n  const pa = Object.entries(pay).sort((a,b) => b[1]-a[1]);\n  $(\"#payTitle\").textContent = ymLabel(cur);\n  const box = $(\"#payBox\"); if (box) box.style.height = Math.max(120, pa.length*40 + 40) + \"px\";\n  const o4 = baseOpts(); o4.indexAxis = \"y\"; o4.interaction = {mode: \"nearest\", intersect: true};\n  o4.plugins.tooltip.callbacks = {label: c => ` ${money(c.parsed.x)}`};\n  o4.scales = {x: {...o4.scales.y}, y: {grid: {display: false}, border: {display: false}, ticks: {color: cssv(\"--ink-2\"), font: {weight: 600}}}};\n  mk(\"cPay\", {type: \"bar\", data: {labels: pa.map(x => x[0]), datasets: [{label: \"Gasto\", data: pa.map(x => x[1]), backgroundColor: s1, borderRadius: 4, borderSkipped: \"left\", maxBarThickness: 20}]}, options: o4});\n\n  $(\"#tbl\").innerHTML = `<thead><tr><th>Mes</th><th>Ingresos</th><th>Gastos</th><th>Inversión</th><th>Balance</th></tr></thead><tbody>` +\n    months.map((m,i) => `<tr><td style=\"text-transform:capitalize\">${ymLabel(m)}</td><td class=\"num\">${money(T[i].entra)}</td><td class=\"num\">${money(T[i].Gasto)}</td><td class=\"num\">${money(T[i][\"Inversión\"])}</td><td class=\"num ${T[i].balance >= 0 ? \"pos\" : \"neg\"}\"><b>${money(T[i].balance)}</b></td></tr>`).join(\"\") + \"</tbody>\";\n}\n\n/* ---------- Formulario ---------- */\nlet edit = null;           // id de la fila que se edita\nlet fTipo = \"Gasto\", fFreq = \"unica\", fScope = \"mes\";\n\nfunction setPressed(container, val, attr=\"v\"){ for (const b of container.querySelectorAll(\"button\")) b.setAttribute(\"aria-pressed\", String(b.dataset[attr] === val)); }\nfunction fillCatOpts(){\n  const base = fTipo === \"Ingreso\" || fTipo === \"Reembolso\" ? CATS_ING : fTipo === \"Inversión\" ? CATS_INV : CATS_GASTO;\n  const used = rows.filter(r => r.tipo === fTipo).map(r => r.cat).filter(Boolean);\n  $(\"#catOpts\").innerHTML = [...new Set([...used, ...base])].map(c => `<option value=\"${esc(c)}\">`).join(\"\");\n  $(\"#descList\").innerHTML = [...new Set(rows.map(r => r.desc))].slice(0,200).map(c => `<option value=\"${esc(c)}\">`).join(\"\");\n}\nfunction syncFreq(){\n  setPressed($(\"#fFreq\"), fFreq);\n  const rec = fFreq === \"mensual\";\n  $(\"#fFechaWrap\").hidden = rec;\n  $(\"#fDiaWrap\").hidden = !rec;\n  $(\"#fFinWrap\").hidden = !rec;\n}\nfunction openSheet(id){\n  const r = id ? findRow(id) : null;\n  edit = r ? r.id : null;\n  $(\"#sheetTitle\").textContent = r ? \"Editar movimiento\" : \"Nuevo movimiento\";\n  fTipo = r?.tipo || \"Gasto\";\n  fFreq = r?.serie ? \"mensual\" : \"unica\";\n  fScope = \"mes\";\n  $(\"#fTipo\").innerHTML = TIPOS.map(t => `<button type=\"button\" data-v=\"${t}\" aria-pressed=\"${t === fTipo}\">${t}</button>`).join(\"\");\n  $(\"#fMet\").innerHTML = `<option value=\"\">—</option>` + [...new Set([...METODOS, ...rows.map(x => x.met).filter(Boolean)])].map(m => `<option>${esc(m)}</option>`).join(\"\");\n  $(\"#fMonto\").value = r ? money(r.monto) : \"\";\n  $(\"#fDesc\").value = r ? r.desc : \"\";\n  $(\"#fCat\").value = r?.cat || \"\";\n  $(\"#fMet\").value = r?.met || \"\";\n  const today = new Date(), defDay = cur === ymNow() ? today.getDate() : 1;\n  $(\"#fFecha\").value = r ? r.fecha : dateIn(cur, defDay);\n  const info = r ? parseSerie(r) : null;\n  $(\"#fDia\").value = r ? Number(r.fecha.slice(8)) : Math.min(defDay, 28);\n  $(\"#fFin\").value = info ? (serieFin(seriesRows(info.id)) || \"\") : \"\";\n  $(\"#scopeWrap\").hidden = !(r && r.serie);\n  setPressed($(\"#fScope\"), fScope);\n  $(\"#fFreq\").querySelectorAll(\"button\").forEach(b => b.disabled = !!r);\n  $(\"#delBtn\").hidden = !r;\n  $(\"#delConfirm\").hidden = true;\n  syncFreq(); fillCatOpts();\n  $(\"#scrim\").hidden = false; $(\"#sheet\").hidden = false;\n  setTimeout(() => { if (!r) $(\"#fMonto\").focus(); }, 60);\n}\nfunction closeSheet(){ $(\"#scrim\").hidden = true; $(\"#sheet\").hidden = true; edit = null; }\n\nfunction submit(e){\n  e.preventDefault();\n  const monto = parseMonto($(\"#fMonto\").value);\n  const desc = $(\"#fDesc\").value.trim().slice(0, 200);\n  if (!monto){ toast(\"Escribe un monto mayor a 0\"); $(\"#fMonto\").focus(); return; }\n  if (!desc){ toast(\"Escribe una descripción\"); $(\"#fDesc\").focus(); return; }\n  const cat = $(\"#fCat\").value.trim().replace(/,/g, \" \").slice(0, 80), met = $(\"#fMet\").value;\n  const dia = Math.max(1, Math.min(31, Number($(\"#fDia\").value) || 1));\n  const fin = $(\"#fFin\").value || null;\n  const fecha = $(\"#fFecha\").value || dateIn(cur, 1);\n  const base = {desc, tipo: fTipo, monto, cat, met};\n\n  if (!edit){\n    let r;\n    if (fFreq === \"mensual\"){\n      if (fin && fin < cur){ toast(\"La fecha «Hasta» no puede ser antes de \" + ymLabel(cur)); return; }\n      r = {id: \"tmp_\"+rid(), ...base, frec: \"mensual\", pagado: false, omit: false, serie: mkSerie(rid(), fin, dia), fecha: dateIn(cur, dia)};\n      toast(\"Guardado. Se repetirá cada mes desde \" + ymLabel(cur));\n    } else {\n      r = {id: \"tmp_\"+rid(), ...base, frec: \"unica\", pagado: false, omit: false, serie: \"\", fecha};\n      toast(\"Guardado\");\n    }\n    rows.push(r); send({t: \"create\", rows: [r]});\n    closeSheet();\n    if (ymOf(r.fecha) !== cur) goTo(ymOf(r.fecha)); else render();\n    return;\n  }\n\n  const r = findRow(edit);\n  if (!r){ closeSheet(); return; }\n  if (!r.serie){\n    Object.assign(r, base, {fecha});\n    send({t: \"update\", updates: [{id: r.id, ...base, fecha}]});\n    toast(\"Cambios guardados\");\n    closeSheet();\n    if (ymOf(fecha) !== cur) goTo(ymOf(fecha)); else render();\n    return;\n  }\n\n  // Ítem mensual\n  const info = parseSerie(r), ym = ymOf(r.fecha);\n  const list = seriesRows(info.id);\n  if (fin && fin < ymOf(list[0].fecha)){ toast(\"La fecha «Hasta» no puede ser antes del primer mes\"); return; }\n  const targets = fScope === \"mes\" ? [r] : fScope === \"desde\" ? list.filter(x => ymOf(x.fecha) >= ym) : list;\n  const tset = new Set(targets.map(x => x.id));\n  const updates = [];\n  for (const x of list){\n    const u = {id: x.id};\n    const xi = parseSerie(x);\n    const inT = tset.has(x.id);\n    const newSerie = mkSerie(info.id, fin, fScope !== \"mes\" && inT ? dia : xi.dia, fScope === \"mes\" ? (inT || xi.aj) : (inT ? false : xi.aj));\n    if (newSerie !== x.serie){ u.serie = newSerie; x.serie = newSerie; }\n    if (tset.has(x.id)){\n      const f = dateIn(ymOf(x.fecha), dia);\n      Object.assign(u, base, {fecha: f}); Object.assign(x, base, {fecha: f});\n    }\n    if (Object.keys(u).length > 1) updates.push(u);\n  }\n  // Si se puso una fecha «Hasta», se quitan los meses posteriores.\n  const sobran = fin ? list.filter(x => ymOf(x.fecha) > fin) : [];\n  if (sobran.length){\n    rows = rows.filter(x => !sobran.includes(x));\n    const drop = new Set(sobran.map(x => x.id));\n    send({t: \"update\", updates: updates.filter(u => !drop.has(u.id))});\n    send({t: \"removeSeries\", serie: info.id, desde: ymAdd(fin, 1) + \"-01\"});\n  } else if (updates.length) send({t: \"update\", updates});\n  toast(fScope === \"mes\" ? \"Ajustado solo para \" + ymLabel(ym) : fScope === \"desde\" ? \"Actualizado desde \" + ymLabel(ym) : \"Actualizado en todos los meses\");\n  closeSheet(); render();\n}\n\nfunction askDelete(){\n  const r = findRow(edit); if (!r) return;\n  const box = $(\"#delConfirm\"); box.hidden = false;\n  if (!r.serie){\n    $(\"#delMsg\").textContent = \"¿Eliminar «\" + r.desc + \"»?\";\n    $(\"#delBtns\").innerHTML = `<button class=\"btn danger\" type=\"button\" data-del=\"todo\">Sí, eliminar</button>`;\n  } else {\n    $(\"#delMsg\").textContent = \"«\" + r.desc + \"» se repite cada mes. ¿Qué quieres eliminar?\";\n    $(\"#delBtns\").innerHTML = `<button class=\"btn\" type=\"button\" data-del=\"mes\">Solo ${esc(ymLabel(ymOf(r.fecha)))}</button><button class=\"btn\" type=\"button\" data-del=\"desde\">Desde este mes en adelante</button><button class=\"btn danger\" type=\"button\" data-del=\"todo\">Todos los meses</button>`;\n  }\n  box.scrollIntoView({block: \"nearest\", behavior: \"smooth\"});\n}\nfunction doDelete(mode){\n  const r = findRow(edit); if (!r) return;\n  if (!r.serie){\n    rows = rows.filter(x => x !== r); send({t: \"remove\", ids: [r.id]});\n  } else {\n    const info = parseSerie(r), ym = ymOf(r.fecha), list = seriesRows(info.id);\n    if (mode === \"mes\"){\n      r.omit = true; send({t: \"update\", updates: [{id: r.id, omit: true}]});\n    } else if (mode === \"todo\"){\n      rows = rows.filter(x => serieId(x) !== info.id);\n      send({t: \"removeSeries\", serie: info.id});\n    } else {\n      const quedan = list.filter(x => ymOf(x.fecha) < ym);\n      rows = rows.filter(x => serieId(x) !== info.id || ymOf(x.fecha) < ym);\n      const fin = ymAdd(ym, -1);\n      const updates = quedan.map(x => { const xi = parseSerie(x); const s = mkSerie(info.id, fin, xi.dia, xi.aj); x.serie = s; return {id: x.id, serie: s}; });\n      if (updates.length) send({t: \"update\", updates});\n      send({t: \"removeSeries\", serie: info.id, desde: ym + \"-01\"});\n    }\n  }\n  closeSheet(); render(); toast(\"Eliminado\");\n}\nfunction toggleHecho(id){\n  const r = findRow(id); if (!r) return;\n  r.pagado = !r.pagado; send({t: \"update\", updates: [{id: r.id, pagado: r.pagado}]}); render();\n}\n\n/* ---------- Exportar / copias (modo local) ---------- */\nfunction download(name, text, type){\n  try{\n    const blob = new Blob([text], {type}); const a = document.createElement(\"a\");\n    a.href = URL.createObjectURL(blob); a.download = name; document.body.appendChild(a); a.click();\n    setTimeout(() => { URL.revokeObjectURL(a.href); a.remove(); }, 500);\n    toast(\"Descargando \" + name);\n  }catch(e){ copyText(text); }\n}\nfunction copyText(text){\n  const done = () => toast(\"Copiado al portapapeles\");\n  if (navigator.clipboard?.writeText) navigator.clipboard.writeText(text).then(done).catch(() => fallbackCopy(text));\n  else fallbackCopy(text);\n}\nfunction fallbackCopy(text){ const t = $(\"#bkPaste\"); t.value = text; t.focus(); t.select(); toast(\"Selecciona y copia el texto del cuadro\"); }\nfunction csvFor(months){\n  const q = v => `\"${String(v ?? \"\").replace(/\"/g, '\"\"')}\"`;\n  const out = [[\"Descripción\",\"Tipo\",\"Gasto\",\"Ingreso\",\"Fecha\",\"Método de Pago\",\"Categoría\",\"Frecuencia\",\"Pagado\"].map(q).join(\",\")];\n  for (const ym of months) for (const r of occurrences(ym)){\n    const s = SIGNO[r.tipo];\n    out.push([r.desc, r.tipo, s < 0 ? r.monto : \"\", s > 0 ? r.monto : \"\", r.fecha, r.met, r.cat, r.serie ? \"Mensual\" : \"Una vez\", r.pagado ? \"Sí\" : \"No\"].map(q).join(\",\"));\n  }\n  return \"﻿\" + out.join(\"\\n\");\n}\nfunction restore(text){\n  try{\n    const s = JSON.parse(text);\n    if (!s || !Array.isArray(s.rows)) throw 0;\n    rows = s.rows.filter(r => r && r.fecha && r.desc); isSample = false; localSave(); render(); toast(\"Copia restaurada: \" + rows.length + \" movimientos\");\n  }catch(e){ toast(\"Ese texto no es una copia válida de Mis Finanzas\"); }\n}\n\n/* ---------- Toast ---------- */\nlet tt;\nfunction toast(msg){ const t = $(\"#toast\"); t.textContent = msg; t.hidden = false; clearTimeout(tt); tt = setTimeout(() => t.hidden = true, 2400); }\n\n/* ---------- Eventos ---------- */\n$(\"#prevM\").onclick = () => goTo(ymAdd(cur, -1));\n$(\"#nextM\").onclick = () => goTo(ymAdd(cur, 1));\n$(\"#monthLbl\").onclick = () => goTo(ymNow());\ndocument.querySelector(\".tabs\").addEventListener(\"click\", e => { const b = e.target.closest(\"button[data-tab]\"); if (b){ tab = b.dataset.tab; render(); window.scrollTo({top: 0}); } });\n$(\"#filterChips\").addEventListener(\"click\", e => { const b = e.target.closest(\".chip\"); if (!b) return; filtro = b.dataset.f; setPressed($(\"#filterChips\"), filtro, \"f\"); renderMov(); });\n$(\"#q\").addEventListener(\"input\", renderMov);\ndocument.querySelector(\".seg\").addEventListener(\"click\", e => { const b = e.target.closest(\"button\"); if (!b) return; rango = Number(b.dataset.r); setPressed(document.querySelector(\".seg\"), String(rango), \"r\"); renderGraf(); });\n$(\"#addBtn\").onclick = () => openSheet(null);\n$(\"#scrim\").onclick = closeSheet;\n$(\"#cancelBtn\").onclick = closeSheet;\ndocument.addEventListener(\"keydown\", e => { if (e.key === \"Escape\" && !$(\"#sheet\").hidden) closeSheet(); });\n$(\"#form\").addEventListener(\"submit\", submit);\n$(\"#fTipo\").addEventListener(\"click\", e => { const b = e.target.closest(\"button\"); if (!b) return; fTipo = b.dataset.v; setPressed($(\"#fTipo\"), fTipo); fillCatOpts(); });\n$(\"#fFreq\").addEventListener(\"click\", e => { const b = e.target.closest(\"button\"); if (!b || b.disabled) return; fFreq = b.dataset.v; syncFreq(); });\n$(\"#fScope\").addEventListener(\"click\", e => { const b = e.target.closest(\"button\"); if (!b) return; fScope = b.dataset.v; setPressed($(\"#fScope\"), fScope); });\n$(\"#fMonto\").addEventListener(\"input\", e => { const n = parseMonto(e.target.value); e.target.value = n ? money(n) : \"\"; });\n$(\"#delBtn\").onclick = askDelete;\n$(\"#delBtns\").addEventListener(\"click\", e => { const b = e.target.closest(\"button[data-del]\"); if (b) doDelete(b.dataset.del); });\n\nfunction onListClick(e){\n  const row = e.target.closest(\".row\"); if (!row) return;\n  if (e.target.closest(\"[data-check]\")){ e.stopPropagation(); toggleHecho(row.dataset.id); return; }\n  openSheet(row.dataset.id);\n}\nfunction onListKey(e){ if ((e.key === \"Enter\" || e.key === \" \") && e.target.classList.contains(\"row\")){ e.preventDefault(); openSheet(e.target.dataset.id); } }\nfor (const id of [\"#movList\", \"#pendList\"]){ $(id).addEventListener(\"click\", onListClick); $(id).addEventListener(\"keydown\", onListKey); }\n\n$(\"#clearEx\").onclick = () => { rows = []; isSample = false; localSave(); render(); toast(\"Listo. Toca «Agregar» para crear tu primer movimiento\"); };\n$(\"#bkDown\").onclick = () => download(\"mis-finanzas-\" + new Date().toISOString().slice(0,10) + \".json\", JSON.stringify({rows}, null, 1), \"application/json\");\n$(\"#bkCopy\").onclick = () => copyText(JSON.stringify({rows}));\n$(\"#bkFile\").onchange = e => { const f = e.target.files[0]; if (!f) return; const r = new FileReader(); r.onload = () => restore(r.result); r.readAsText(f); e.target.value = \"\"; };\n$(\"#bkRestore\").onclick = () => { const v = $(\"#bkPaste\").value.trim(); if (v) restore(v); else toast(\"Pega primero el texto de la copia\"); };\n$(\"#csvMonth\").onclick = () => download(\"finanzas-\" + cur + \".csv\", csvFor([cur]), \"text/csv\");\n$(\"#csvYear\").onclick = () => { const y = cur.slice(0,4); const ms = []; for (let m = 1; m <= 12; m++) ms.push(y + \"-\" + pad(m)); download(\"finanzas-\" + y + \".csv\", csvFor(ms), \"text/csv\"); };\n$(\"#wipe\").onclick = () => { $(\"#wipeConfirm\").hidden = false; };\n$(\"#wipeNo\").onclick = () => { $(\"#wipeConfirm\").hidden = true; };\n$(\"#wipeYes\").onclick = () => { rows = []; isSample = false; localSave(); $(\"#wipeConfirm\").hidden = true; render(); toast(\"Datos borrados\"); };\nasync function reloadAll(){ loaded = null; syncError = null; $(\"#errBanner\").hidden = true; await goTo(cur); }\n$(\"#retryBtn\").onclick = reloadAll;\n$(\"#reloadBtn\").onclick = async () => { await reloadAll(); toast(\"Datos actualizados desde Notion\"); };\n\n// tema\nfunction applyTheme(t){ if (t) document.documentElement.setAttribute(\"data-theme\", t); else document.documentElement.removeAttribute(\"data-theme\"); }\ntry{ applyTheme(localStorage.getItem(\"fin_theme\")); }catch(e){}\n$(\"#themeBtn\").onclick = () => {\n  const dark = document.documentElement.getAttribute(\"data-theme\") === \"dark\" || (!document.documentElement.getAttribute(\"data-theme\") && matchMedia(\"(prefers-color-scheme: dark)\").matches);\n  const next = dark ? \"light\" : \"dark\"; applyTheme(next); try{ localStorage.setItem(\"fin_theme\", next); }catch(e){} render();\n};\nmatchMedia(\"(prefers-color-scheme: dark)\").addEventListener?.(\"change\", render);\n\n// Aviso si se cierra con cambios sin enviar a Notion.\nwindow.addEventListener(\"beforeunload\", e => { if (REMOTE && pending){ e.preventDefault(); e.returnValue = \"\"; } });\n\ntry{ const t = sessionStorage.getItem(\"fin_tab\"); if (t) tab = t; }catch(e){}\nif (location.hash && [\"resumen\",\"mov\",\"graf\"].includes(location.hash.slice(1))) tab = location.hash.slice(1);\n\nif (!REMOTE){ const s = localLoad(); rows = s.rows; isSample = !!s.sample; }\ngoTo(cur);\n})();\n</script>\n</body>\n</html>\n";

const NOTION = "https://api.notion.com/v1";
const NOTION_VERSION = "2022-06-28";
const DATE_RE = /^\d{4}-\d{2}-\d{2}$/;
const ID_RE = /^[0-9a-f]{8}-?[0-9a-f]{4}-?[0-9a-f]{4}-?[0-9a-f]{4}-?[0-9a-f]{12}$/i;
const SERIE_RE = /^[a-z0-9]{4,24}$/;
const TIPOS = ["Gasto", "Ingreso", "Inversión", "Transferencia", "Reembolso"];

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    try {
      if (url.pathname === "/" && request.method === "GET") return servePage(url, env);
      if (url.pathname.startsWith("/api/")) {
        if (!env.NOTION_TOKEN || !env.APP_KEY || !env.DATABASE_ID)
          return json({ error: "Falta configurar NOTION_TOKEN, APP_KEY o DATABASE_ID en Cloudflare" }, 500);
        if (!sameKey(request.headers.get("x-app-key") || "", env.APP_KEY))
          return json({ error: "Clave incorrecta" }, 401);
        return await route(request, url, env);
      }
      return new Response("No encontrado", { status: 404 });
    } catch (err) {
      return json({ error: err.message || "Error inesperado" }, err.status || 500);
    }
  },
};

function servePage(url, env) {
  const k = url.searchParams.get("k") || "";
  if (!env.APP_KEY || !sameKey(k, env.APP_KEY)) {
    return new Response(
      '<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width"><body style="font:16px system-ui;padding:24px">' +
        "<h2>Mis Finanzas</h2><p>Este enlace no tiene la clave correcta. Abre la app con el enlace completo que termina en <code>?k=tu-clave</code>.</p>",
      { status: 401, headers: { "content-type": "text/html; charset=utf-8" } }
    );
  }
  const cfg = `<script>window.FIN_CONFIG={api:"/api",key:${JSON.stringify(k).replace(/</g, "\\u003c")}};</script>`;
  return new Response(APP_HTML.replace("</head>", cfg + "</head>"), {
    headers: {
      "content-type": "text/html; charset=utf-8",
      "cache-control": "no-store",
      "referrer-policy": "no-referrer",
    },
  });
}

async function route(request, url, env) {
  const p = url.pathname, m = request.method;

  if (p === "/api/rows" && m === "GET") {
    const from = url.searchParams.get("from"), to = url.searchParams.get("to");
    if (!DATE_RE.test(from || "") || !DATE_RE.test(to || "")) return json({ error: "Fechas inválidas" }, 400);
    const filter = { and: [
      { property: "Fecha", date: { on_or_after: from } },
      { property: "Fecha", date: { on_or_before: to } },
    ] };
    const pages = await queryAll(env, filter, 30);
    return json({ rows: pages.map(fromPage).filter(Boolean) });
  }

  if (p === "/api/rows" && m === "POST") {
    const body = await readBody(request);
    const list = arr(body.rows, 25);
    const out = [];
    for (const r of list) {
      const page = await notion(env, "POST", "/pages", {
        parent: { database_id: env.DATABASE_ID },
        properties: toProps(r, true),
      });
      out.push(fromPage(page));
    }
    return json({ rows: out });
  }

  if (p === "/api/rows" && m === "PATCH") {
    const body = await readBody(request);
    const list = arr(body.updates, 25);
    for (const u of list) {
      if (!ID_RE.test(u.id || "")) throw httpError("Id inválido", 400);
      await notion(env, "PATCH", "/pages/" + u.id, { properties: toProps(u, false) });
    }
    return json({ ok: true });
  }

  if (p === "/api/rows/delete" && m === "POST") {
    const body = await readBody(request);
    const ids = arr(body.ids, 25);
    for (const id of ids) {
      if (!ID_RE.test(id || "")) throw httpError("Id inválido", 400);
      await notion(env, "PATCH", "/pages/" + id, { archived: true });
    }
    return json({ ok: true });
  }

  // Borra las filas de un ítem mensual (todas, o desde una fecha). Por partes, para no
  // pasar el límite de peticiones de Cloudflare; la app repite mientras "remaining" sea true.
  if (p === "/api/series/delete" && m === "POST") {
    const body = await readBody(request);
    if (!SERIE_RE.test(body.serie || "")) return json({ error: "Serie inválida" }, 400);
    const and = [{ property: "Serie", rich_text: { starts_with: body.serie + "|" } }];
    if (body.desde) {
      if (!DATE_RE.test(body.desde)) return json({ error: "Fecha inválida" }, 400);
      and.push({ property: "Fecha", date: { on_or_after: body.desde } });
    }
    const res = await notion(env, "POST", `/databases/${env.DATABASE_ID}/query`, { filter: { and }, page_size: 30 });
    for (const page of res.results) await notion(env, "PATCH", "/pages/" + page.id, { archived: true });
    return json({ deleted: res.results.length, remaining: !!res.has_more });
  }

  return json({ error: "Ruta no encontrada" }, 404);
}

/* ---------- Notion ---------- */
async function notion(env, method, path, body) {
  for (let attempt = 0; attempt < 4; attempt++) {
    const res = await fetch(NOTION + path, {
      method,
      headers: {
        authorization: "Bearer " + env.NOTION_TOKEN,
        "notion-version": NOTION_VERSION,
        "content-type": "application/json",
      },
      body: body ? JSON.stringify(body) : undefined,
    });
    if (res.status === 429 && attempt < 3) {
      const wait = Math.min(Number(res.headers.get("retry-after")) || 1, 3);
      await new Promise((r) => setTimeout(r, wait * 1000));
      continue;
    }
    const data = await res.json().catch(() => ({}));
    if (!res.ok) {
      const msg = res.status === 401 ? "La clave de Notion (NOTION_TOKEN) no es válida"
        : res.status === 404 ? "Notion no encuentra la base. Conecta la integración a la página (••• → Conexiones)"
        : data.message || "Error de Notion " + res.status;
      throw httpError(msg, 502);
    }
    return data;
  }
}

async function queryAll(env, filter, maxPages) {
  const out = [];
  let cursor;
  for (let i = 0; i < maxPages; i++) {
    const res = await notion(env, "POST", `/databases/${env.DATABASE_ID}/query`, {
      filter, sorts: [{ property: "Fecha", direction: "ascending" }], page_size: 100,
      ...(cursor ? { start_cursor: cursor } : {}),
    });
    out.push(...res.results);
    if (!res.has_more) break;
    cursor = res.next_cursor;
  }
  return out;
}

const plain = (rt) => (rt || []).map((t) => t.plain_text).join("");

function fromPage(page) {
  const p = page.properties || {};
  const fecha = p["Fecha"]?.date?.start?.slice(0, 10);
  if (!fecha) return null;
  return {
    id: page.id,
    desc: plain(p["Descripción"]?.title) || "Sin descripción",
    tipo: p["Tipo"]?.select?.name || "Gasto",
    monto: Number(p["Monto"]?.number) || 0,
    fecha,
    cat: p["Categoría"]?.select?.name || "",
    met: p["Método de Pago"]?.select?.name || "",
    frec: p["Frecuencia"]?.select?.name === "Mensual" ? "mensual" : "unica",
    pagado: !!p["Pagado"]?.checkbox,
    serie: plain(p["Serie"]?.rich_text),
    omit: !!p["Omitido"]?.checkbox,
  };
}

const selectName = (v) => {
  const s = String(v || "").replace(/,/g, " ").trim().slice(0, 90);
  return s ? { select: { name: s } } : { select: null };
};

// Convierte una fila de la app en propiedades de Notion. Solo incluye los campos enviados.
function toProps(r, isNew) {
  const props = {};
  const has = (k) => isNew || Object.prototype.hasOwnProperty.call(r, k);
  if (has("desc")) props["Descripción"] = { title: [{ text: { content: String(r.desc || "Sin descripción").slice(0, 200) } }] };
  if (has("tipo")) {
    if (!TIPOS.includes(r.tipo)) throw httpError("Tipo inválido", 400);
    props["Tipo"] = { select: { name: r.tipo } };
  }
  if (has("monto")) {
    const n = Number(r.monto);
    if (!Number.isFinite(n) || n < 0 || n > 1e12) throw httpError("Monto inválido", 400);
    props["Monto"] = { number: n };
  }
  if (has("fecha")) {
    if (!DATE_RE.test(r.fecha || "")) throw httpError("Fecha inválida", 400);
    props["Fecha"] = { date: { start: r.fecha } };
  }
  if (has("cat")) props["Categoría"] = selectName(r.cat);
  if (has("met")) props["Método de Pago"] = selectName(r.met);
  if (isNew) props["Frecuencia"] = { select: { name: r.serie ? "Mensual" : "Una vez" } };
  if (has("pagado")) props["Pagado"] = { checkbox: !!r.pagado };
  if (has("omit")) props["Omitido"] = { checkbox: !!r.omit };
  if (has("serie")) {
    const s = String(r.serie || "").slice(0, 60);
    props["Serie"] = { rich_text: s ? [{ text: { content: s } }] : [] };
  }
  return props;
}

/* ---------- Utilidades ---------- */
function json(data, status = 200) {
  return new Response(JSON.stringify(data), {
    status, headers: { "content-type": "application/json; charset=utf-8", "cache-control": "no-store" },
  });
}
function httpError(message, status) { const e = new Error(message); e.status = status; return e; }
async function readBody(request) {
  try { return await request.json(); } catch { throw httpError("Cuerpo inválido", 400); }
}
function arr(v, max) {
  if (!Array.isArray(v) || v.length > max) throw httpError("Lista inválida", 400);
  return v;
}
function sameKey(a, b) {
  if (typeof a !== "string" || typeof b !== "string" || a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return diff === 0;
}
